func NormalizeVulnerabilityScan(scanner string, raw []byte, defaults map[string]string) (ScanNormalizeResult, error) {
	var root map[string]any
	if err := json.Unmarshal(raw, &root); err != nil {
		return ScanNormalizeResult{}, err
	}
	s := strings.ToLower(strings.TrimSpace(scanner))
	requested := s
	if s == "" {
		s = detectScanner(root)
	}
	out := ScanNormalizeResult{
		Scanner:        s,
		ScannerVersion: defaults["scanner_version"],
		TargetType:     firstNonEmptyV(defaults["target_type"], strV(root["ArtifactType"])),
		TargetRef:      firstNonEmptyV(defaults["target_ref"], defaults["image"], strV(root["ArtifactName"])),
		ImageDigest:    defaults["image_digest"],
		Summary:        map[string]any{},
		Findings:       []VulnerabilityFinding{},
	}
	fallback := false
	switch s {
	case "grype":
		normalizeGrype(root, defaults, &out)
	case "trivy-operator", "vulnerabilityreport":
		out.Scanner = "trivy-operator"
		normalizeTrivyOperator(root, defaults, &out)
	case "trivy":
		out.Scanner = "trivy"
		normalizeTrivy(root, defaults, &out)
	default:
		// Whatever the artifact claimed to be, the reader that actually ran is Trivy's.
		// Recording the requested (or undetected) label here stored rows as
		// scanner="unknown"/"snyk" while every field in them came out of the Trivy
		// reader — the scan list, the audit entry and the DW export then named a
		// parser that never ran.
		out.Scanner = "trivy"
		fallback = true
		normalizeTrivy(root, defaults, &out)
	}
	if out.ImageDigest == "" {
		out.ImageDigest = imageDigestFromRaw(root)
	}
	if out.TargetRef == "" {
		out.TargetRef = out.ImageDigest
	}
	out.Summary = vulnerabilitySummary(out.Findings)
	out.Summary["scanner_detected"] = !fallback
	if fallback {
		if requested != "" && requested != out.Scanner {
			out.Summary["requested_scanner"] = requested
		}
		if len(out.Findings) == 0 {
			// An unreadable artifact and a genuinely clean image both produce zero
			// findings, and the admission gate cannot tell them apart. Say which one
			// this was rather than letting the import read as "no vulnerabilities".
			out.Summary["parse_notice"] = "지원 형식(trivy·grype·trivy-operator)으로 인식되지 않아 Trivy 리더로 읽었고 취약점을 한 건도 찾지 못했습니다. 실제로 깨끗한 이미지인지 형식 불일치인지 구분되지 않으므로 scanner 형식을 확인하세요."
		}
	}
	return out, nil
}
#!/usr/bin/env bash
# Golden Prompt regression gate for CI.
#
# Runs every golden prompt registered in the gateway against the given model(s)
# and fails (exit 1) when the pass rate drops below the threshold — so model or
# prompt changes can't merge if they regress known-good behaviour.
#
# Usage:
#   GATEWAY_URL=http://localhost:9090 ADMIN_TOKEN=... \
#   scripts/golden-regression.sh "gpt-4.1-mini,gpt-4.1" [min_pass_rate] [tag]
#
# Defaults: models from $GOLDEN_MODELS, min_pass_rate=1.0, no tag filter.
set -euo pipefail

GATEWAY_URL="${GATEWAY_URL:-http://localhost:9090}"
MODELS="${1:-${GOLDEN_MODELS:-}}"
MIN_PASS_RATE="${2:-1.0}"
TAG="${3:-}"

if [[ -z "$MODELS" ]]; then
  echo "error: no models given (arg 1 or \$GOLDEN_MODELS)" >&2
  exit 2
fi

# Build a JSON array from the comma-separated model list.
models_json=$(printf '%s' "$MODELS" | awk -v RS=',' 'NF{gsub(/^[ \t]+|[ \t]+$/,"");printf "%s\"%s\"",sep,$0;sep=","}')
payload="{\"models\":[${models_json}],\"min_pass_rate\":${MIN_PASS_RATE}"
if [[ -n "$TAG" ]]; then payload="${payload},\"tag\":\"${TAG}\""; fi
payload="${payload}}"

auth=()
if [[ -n "${ADMIN_TOKEN:-}" ]]; then auth=(-H "Authorization: Bearer ${ADMIN_TOKEN}"); fi

echo "Running golden regression against: ${MODELS} (min_pass_rate=${MIN_PASS_RATE}${TAG:+, tag=$TAG})"
http_code=$(curl -sS -o /tmp/golden_result.json -w '%{http_code}' \
  -X POST "${GATEWAY_URL}/admin/golden-prompts/run?fail_on_regression=1" \
  -H "Content-Type: application/json" "${auth[@]}" \
  -d "$payload")

cat /tmp/golden_result.json
echo

if [[ "$http_code" == "422" ]]; then
  echo "::error::Golden prompt regression detected (pass rate below ${MIN_PASS_RATE})." >&2
  exit 1
fi
if [[ "$http_code" != "200" ]]; then
  echo "error: gateway returned HTTP ${http_code}" >&2
  exit 1
fi
echo "Golden regression gate passed."
